// === Tab: MMs ===
// mariana magalhães — DSG1413 — 2020.1
// Audio-visual enhanced confetti particle system

let p = [];
let cores = [];

function setup() {
  createCanvas(windowWidth, windowHeight);

  cores = [
    color(6, 150, 104), color(107, 221, 140), color(41, 140, 192), 
    color(163, 201, 254), color(174, 115, 251), color(179, 86, 145), color(251, 9, 152), 
    color(250, 175, 227), color(67, 114, 222), color(129, 244, 254), color(118, 138, 96), 
    color(191, 205, 142), color(192, 244, 66), color(202, 81, 0), color(251, 209, 39), color(168, 121, 98), 
    color(101, 241, 18), color(253, 44, 59), color(254, 183, 134), color(201, 34, 214)
  ];

  for (let j = 0; j < 800; j++) {
    let baseCol = cores[j % cores.length];
    let c = color(red(baseCol), green(baseCol), blue(baseCol), 160);
    p.push(new Particle(random(width), random(height), c));
  }
}

function draw() {
  background(10, 10, 16, 40);
  noStroke();

  let bass = (typeof window !== 'undefined' && window.audioLow !== undefined) ? window.audioLow : 0.5;
  let isBeat = (typeof window !== 'undefined' && window.isBeat) ? 1 : 0;
  let speedMultiplier = 1.0 + bass * 2.5 + isBeat * 1.5;

  for (let k = 0; k < p.length; k++) {
    p[k].move(speedMultiplier);
    p[k].draw(bass, isBeat);
  }
}

class Particle {
  constructor(ix, iy, ic) {
    this.x = ix;
    this.y = iy;
    this.c = ic;
    this.vx = random(-1.5, 1.5);
    this.vy = random(-1.5, 1.5);
    this.size = random(8, 20);
    this.rot = random(TWO_PI);
    this.rotSpeed = random(-0.05, 0.05);
  }

  move(speedMult) {
    this.x += (this.vx + random(-0.5, 0.5)) * speedMult;
    this.y += (this.vy + random(-0.5, 0.5)) * speedMult;
    this.rot += this.rotSpeed * speedMult;

    if (this.x < -20) this.x = width + 20;
    if (this.x > width + 20) this.x = -20;
    if (this.y < -20) this.y = height + 20;
    if (this.y > height + 20) this.y = -20;

    if (mouseIsPressed) {
      this.x += random(-5, 5);
      this.y += random(-5, 5);
    }
  }

  draw(bass, isBeat) {
    push();
    translate(this.x, this.y);
    rotate(this.rot);
    fill(this.c);
    let currentSize = this.size * (1.0 + bass * 0.4 + (isBeat ? 0.3 : 0));
    rectMode(CENTER);
    rect(0, 0, currentSize, currentSize * 0.7, 4);
    pop();
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

